44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	} as const satisfies Record<string, number>;
55	
56	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
57	
58	const basePremiumForType = (type: string): number =>
59	  BASE_PREMIUMS[type as InsurableItemType];
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_PREMIUM = 60;
63	
64	const groupByType = (items: Item[]): Map<string, Item[]> => {
65	  const groups = new Map<string, Item[]>();
66	  for (const item of items) {
67	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
68	  }
69	  return groups;
70	};
71	
72	// Items of one type, quoted together. A group of exactly 3 forms a building
73	// block and is offered at a flat base premium; any other size is priced per
74	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
75	// groups, so neither is a block.
76	type AlikeGroup = [type: string, items: Item[]];
77	
78	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
79	  items.length === BLOCK_SIZE;
80	
81	const basePremiumForGroup = (group: AlikeGroup): number => {
82	  const [type, items] = group;
83	  return isBuildingBlock(group)
84	    ? BLOCK_PREMIUM
85	    : items.length * basePremiumForType(type);
86	};
87	
88	const sumBasePremiums = (items: Item[]): number =>
89	  [...groupByType(items)].reduce(
90	    (total, group) => total + basePremiumForGroup(group),
91	    0,
92	  );
93	
94	const CURSE_SURCHARGE_RATE = 0.5;
95	
96	// Item-specific modifiers apply to the base premium of the affected item, not
97	// to the policy total.
98	const sumItemSurcharges = (items: Item[]): number =>
99	  items.reduce(
100	    (total, item) =>
101	      item.cursed
102	        ? total + basePremiumForType(item.type) * CURSE_SURCHARGE_RATE
103	        : total,
104	    0,
105	  );
106	
107	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
108	// rounded, intermediate amounts stay fractional.
109	const roundInMHPCOsFavour = Math.ceil;
110	
111	const quotePremium = (items: Item[]): number => {
112	  const basePremium = sumBasePremiums(items);
113	  const itemSurcharges = sumItemSurcharges(items);
114	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
115	  return roundInMHPCOsFavour(
116	    basePremium + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
117	  );
118	};
119	
120	const runStep = (step: Step): QuoteResult | ClaimResult => {
121	  switch (step.op) {
122	    case "quote":
123	      return { premium: quotePremium(step.items) };
124	    case "claim":
125	      throw new Error("claim steps are not supported yet");
126	  }
127	};
128	
129	export const runScenario = (scenario: Scenario): ScenarioResults => ({
130	  results: scenario.steps.map(runStep),
131	});
