const CURSE_SURCHARGE_RATE = 0.5;

// Item-specific modifiers apply to the base premium of the affected item, not
// to the policy total. Each rule charges its rate on that one item's base
// premium, so a rule is fully described by "when does it apply" and "how much".
interface ItemSurchargeRule {
  appliesTo: (item: Item) => boolean;
  rate: number;
}

const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
];

const surchargeForItem = (item: Item): number =>
  ITEM_SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
    (total, rule) => total + basePremiumForType(item.type) * rule.rate,
    0,
  );

const sumItemSurcharges = (items: Item[]): number =>
  items.reduce((total, item) => total + surchargeForItem(item), 0);

